True def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for r in range(h):
        marks = [c for c, v in enumerate(grid[r]) if v != bg]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != bg]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
    return out
